from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    # Step 1: Remove spaces from the input string
    paren_string = paren_string.replace(" ", "")

    # Step 2: Identify and extract groups of nested parentheses
    groups = []
    current_group = ""
    open_count = 0

    for char in paren_string:
        if char == "(":
            open_count += 1
        elif char == ")":
            open_count -= 1

        current_group += char

        if open_count == 0:
            groups.append(current_group)
            current_group = ""

    # Step 3: Separate the extracted groups into individual strings
    result = [group for group in groups]

    # Step 4: Return the list of separated strings
    return result

